import './styles.css';
import { useState } from 'react';

interface ModelOption {
  id: string;
  name: string;
  category: string;
  co2PerQuery: number; // grams
  description: string;
}

interface UsageScenario {
  id: string;
  name: string;
  queriesPerDay: number;
  description: string;
}

interface EnergySource {
  id: string;
  name: string;
  multiplier: number;
  color: string;
}

const models: ModelOption[] = [
  { id: 'rule-based', name: 'Rule-based System', category: 'Traditional', co2PerQuery: 0.1, description: 'Simple if-then logic, minimal compute' },
  { id: 'small-ml', name: 'Small ML Model', category: 'Traditional', co2PerQuery: 0.5, description: 'Traditional machine learning model' },
  { id: 'small-llm', name: 'Small LLM (7B params)', category: 'LLM', co2PerQuery: 2, description: 'Compact language model' },
  { id: 'medium-llm', name: 'Medium LLM (30B params)', category: 'LLM', co2PerQuery: 5, description: 'Mid-size language model' },
  { id: 'large-llm', name: 'Large LLM (70B+ params)', category: 'LLM', co2PerQuery: 10, description: 'Full-size model like GPT-4' },
];

const usageScenarios: UsageScenario[] = [
  { id: 'light', name: 'Light Use', queriesPerDay: 10, description: 'Occasional queries, research' },
  { id: 'moderate', name: 'Moderate Use', queriesPerDay: 50, description: 'Regular daily use' },
  { id: 'heavy', name: 'Heavy Use', queriesPerDay: 200, description: 'Intensive use, multiple users' },
  { id: 'org-wide', name: 'Organization-wide', queriesPerDay: 1000, description: 'Deployed across organization' },
];

const energySources: EnergySource[] = [
  { id: 'coal', name: 'Coal-heavy Grid', multiplier: 2.0, color: '#374151' },
  { id: 'mixed', name: 'Mixed Grid (Average)', multiplier: 1.0, color: '#6b7280' },
  { id: 'low-carbon', name: 'Low-carbon Grid', multiplier: 0.4, color: '#22c55e' },
  { id: 'renewable', name: '100% Renewable', multiplier: 0.1, color: '#10b981' },
];

const comparisons = [
  { name: 'Google search', co2: 0.2, icon: '🔍' },
  { name: 'Email sent', co2: 4, icon: '📧' },
  { name: 'Smartphone charge', co2: 8, icon: '🔋' },
  { name: 'Cup of coffee', co2: 50, icon: '☕' },
  { name: '1 km by car', co2: 120, icon: '🚗' },
  { name: '1 km by plane', co2: 250, icon: '✈️' },
];

function ModelSelector({
  selected,
  onSelect,
}: {
  selected: string;
  onSelect: (id: string) => void;
}) {
  return (
    <div className="selector-section">
      <h3>1. Choose AI Type</h3>
      <div className="model-grid">
        {models.map((model) => (
          <div
            key={model.id}
            className={`model-card ${selected === model.id ? 'selected' : ''}`}
            onClick={() => onSelect(model.id)}
          >
            <div className="model-category">{model.category}</div>
            <div className="model-name">{model.name}</div>
            <div className="model-co2">{model.co2PerQuery}g CO₂/query</div>
            <div className="model-desc">{model.description}</div>
          </div>
        ))}
      </div>
    </div>
  );
}

function UsageSelector({
  selected,
  onSelect,
}: {
  selected: string;
  onSelect: (id: string) => void;
}) {
  return (
    <div className="selector-section">
      <h3>2. Usage Pattern</h3>
      <div className="usage-options">
        {usageScenarios.map((scenario) => (
          <button
            key={scenario.id}
            className={`usage-btn ${selected === scenario.id ? 'selected' : ''}`}
            onClick={() => onSelect(scenario.id)}
          >
            <div className="usage-name">{scenario.name}</div>
            <div className="usage-queries">{scenario.queriesPerDay} queries/day</div>
          </button>
        ))}
      </div>
    </div>
  );
}

function EnergySelector({
  selected,
  onSelect,
}: {
  selected: string;
  onSelect: (id: string) => void;
}) {
  return (
    <div className="selector-section">
      <h3>3. Energy Source</h3>
      <div className="energy-options">
        {energySources.map((source) => (
          <button
            key={source.id}
            className={`energy-btn ${selected === source.id ? 'selected' : ''}`}
            onClick={() => onSelect(source.id)}
            style={{
              borderColor: selected === source.id ? source.color : undefined,
              backgroundColor: selected === source.id ? source.color + '20' : undefined,
            }}
          >
            <div className="energy-dot" style={{ backgroundColor: source.color }} />
            <span>{source.name}</span>
          </button>
        ))}
      </div>
    </div>
  );
}

function Results({
  modelId,
  usageId,
  energyId,
}: {
  modelId: string;
  usageId: string;
  energyId: string;
}) {
  const model = models.find((m) => m.id === modelId)!;
  const usage = usageScenarios.find((u) => u.id === usageId)!;
  const energy = energySources.find((e) => e.id === energyId)!;

  const dailyCO2 = model.co2PerQuery * usage.queriesPerDay * energy.multiplier;
  const monthlyCO2 = dailyCO2 * 30;
  const yearlyCO2 = dailyCO2 * 365;

  const formatCO2 = (grams: number) => {
    if (grams >= 1000) {
      return `${(grams / 1000).toFixed(1)} kg`;
    }
    return `${Math.round(grams)} g`;
  };

  return (
    <div className="results-panel">
      <h2>Environmental Impact</h2>

      <div className="results-grid">
        <div className="result-card">
          <div className="result-label">Daily</div>
          <div className="result-value">{formatCO2(dailyCO2)}</div>
          <div className="result-unit">CO₂</div>
        </div>
        <div className="result-card">
          <div className="result-label">Monthly</div>
          <div className="result-value">{formatCO2(monthlyCO2)}</div>
          <div className="result-unit">CO₂</div>
        </div>
        <div className="result-card highlight">
          <div className="result-label">Yearly</div>
          <div className="result-value">{formatCO2(yearlyCO2)}</div>
          <div className="result-unit">CO₂</div>
        </div>
      </div>

      <div className="comparison-section">
        <h3>That's equivalent to:</h3>
        <div className="comparison-list">
          {comparisons.map((item) => {
            const equivalent = Math.round(yearlyCO2 / item.co2);
            if (equivalent < 1) return null;
            return (
              <div key={item.name} className="comparison-item">
                <span className="comparison-icon">{item.icon}</span>
                <span className="comparison-count">{equivalent.toLocaleString()}</span>
                <span className="comparison-name">{item.name}{equivalent !== 1 ? 's' : ''}</span>
              </div>
            );
          })}
        </div>
      </div>

      <div className="insight-box">
        <h3>💡 Key Insight</h3>
        {energy.multiplier > 1 && (
          <p>Using a <strong>renewable energy provider</strong> could reduce this impact by up to <strong>{Math.round((1 - 0.1/energy.multiplier) * 100)}%</strong>.</p>
        )}
        {model.co2PerQuery >= 5 && (
          <p>Consider whether a <strong>smaller model</strong> could meet your needs—it could reduce impact by <strong>{Math.round((1 - 2/model.co2PerQuery) * 100)}%</strong>.</p>
        )}
        {energy.multiplier <= 0.4 && model.co2PerQuery <= 2 && (
          <p>Great choices! You're using efficient AI with clean energy. Consider reducing unnecessary queries to minimize impact further.</p>
        )}
      </div>
    </div>
  );
}

export default function App() {
  const [selectedModel, setSelectedModel] = useState('medium-llm');
  const [selectedUsage, setSelectedUsage] = useState('moderate');
  const [selectedEnergy, setSelectedEnergy] = useState('mixed');

  return (
    <div className="app">
      <header className="header">
        <h1>AI Carbon Calculator</h1>
        <p className="subtitle">
          Explore the environmental impact of different AI choices
        </p>
      </header>

      <div className="main-content">
        <div className="selectors-column">
          <ModelSelector selected={selectedModel} onSelect={setSelectedModel} />
          <UsageSelector selected={selectedUsage} onSelect={setSelectedUsage} />
          <EnergySelector selected={selectedEnergy} onSelect={setSelectedEnergy} />
        </div>

        <div className="results-column">
          <Results
            modelId={selectedModel}
            usageId={selectedUsage}
            energyId={selectedEnergy}
          />

          <div className="disclaimer">
            <strong>Note:</strong> These are illustrative estimates based on published research. Actual emissions vary by provider, model version, and infrastructure.
          </div>
        </div>
      </div>
    </div>
  );
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, sans-serif;
  background: linear-gradient(135deg, #065f46 0%, #10b981 100%);
  min-height: 100vh;
  padding: 1.5rem 1rem;
}

.app {
  max-width: 1100px;
  margin: 0 auto;
}

.header {
  text-align: center;
  margin-bottom: 1.5rem;
}

h1 {
  color: white;
  font-size: 1.75rem;
  margin-bottom: 0.5rem;
}

.subtitle {
  color: rgba(255, 255, 255, 0.9);
  font-size: 0.95rem;
}

.main-content {
  display: grid;
  grid-template-columns: 1fr 340px;
  gap: 1.5rem;
}

@media (max-width: 900px) {
  .main-content {
    grid-template-columns: 1fr;
  }
}

.selectors-column {
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

.selector-section {
  background: white;
  border-radius: 0.75rem;
  padding: 1.25rem;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
}

.selector-section h3 {
  font-size: 0.95rem;
  color: #1f2937;
  margin-bottom: 1rem;
}

.model-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: 0.75rem;
}

.model-card {
  padding: 0.75rem;
  border: 2px solid #e5e7eb;
  border-radius: 0.5rem;
  cursor: pointer;
  transition: all 0.15s;
}

.model-card:hover {
  border-color: #10b981;
  background: #f0fdf4;
}

.model-card.selected {
  border-color: #10b981;
  background: #d1fae5;
}

.model-category {
  font-size: 0.65rem;
  text-transform: uppercase;
  color: #6b7280;
  margin-bottom: 0.25rem;
}

.model-name {
  font-weight: 600;
  font-size: 0.85rem;
  color: #1f2937;
  margin-bottom: 0.25rem;
}

.model-co2 {
  font-size: 0.9rem;
  font-weight: 700;
  color: #059669;
  margin-bottom: 0.25rem;
}

.model-desc {
  font-size: 0.7rem;
  color: #6b7280;
  line-height: 1.3;
}

.usage-options {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 0.5rem;
}

@media (max-width: 600px) {
  .usage-options {
    grid-template-columns: repeat(2, 1fr);
  }
}

.usage-btn {
  padding: 0.75rem 0.5rem;
  border: 2px solid #e5e7eb;
  border-radius: 0.5rem;
  background: white;
  cursor: pointer;
  transition: all 0.15s;
  text-align: center;
}

.usage-btn:hover {
  border-color: #10b981;
}

.usage-btn.selected {
  border-color: #10b981;
  background: #d1fae5;
}

.usage-name {
  font-weight: 600;
  font-size: 0.8rem;
  color: #1f2937;
}

.usage-queries {
  font-size: 0.7rem;
  color: #6b7280;
  margin-top: 0.25rem;
}

.energy-options {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 0.5rem;
}

.energy-btn {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.6rem 0.75rem;
  border: 2px solid #e5e7eb;
  border-radius: 0.5rem;
  background: white;
  cursor: pointer;
  transition: all 0.15s;
  font-size: 0.8rem;
  color: #1f2937;
}

.energy-btn:hover {
  border-color: #9ca3af;
}

.energy-dot {
  width: 12px;
  height: 12px;
  border-radius: 50%;
}

/* Results Panel */
.results-column {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.results-panel {
  background: white;
  border-radius: 0.75rem;
  padding: 1.25rem;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.15);
}

.results-panel h2 {
  font-size: 1rem;
  color: #1f2937;
  margin-bottom: 1rem;
}

.results-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0.5rem;
  margin-bottom: 1.25rem;
}

.result-card {
  text-align: center;
  padding: 0.75rem;
  background: #f3f4f6;
  border-radius: 0.5rem;
}

.result-card.highlight {
  background: #d1fae5;
}

.result-label {
  font-size: 0.65rem;
  text-transform: uppercase;
  color: #6b7280;
}

.result-value {
  font-size: 1.25rem;
  font-weight: 700;
  color: #1f2937;
}

.result-card.highlight .result-value {
  color: #047857;
}

.result-unit {
  font-size: 0.7rem;
  color: #6b7280;
}

.comparison-section {
  margin-bottom: 1rem;
}

.comparison-section h3 {
  font-size: 0.85rem;
  color: #4b5563;
  margin-bottom: 0.75rem;
}

.comparison-list {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.comparison-item {
  display: flex;
  align-items: center;
  gap: 0.35rem;
  background: #f9fafb;
  padding: 0.4rem 0.6rem;
  border-radius: 0.375rem;
  font-size: 0.75rem;
}

.comparison-icon {
  font-size: 1rem;
}

.comparison-count {
  font-weight: 700;
  color: #1f2937;
}

.comparison-name {
  color: #6b7280;
}

.insight-box {
  background: #eff6ff;
  border: 1px solid #bfdbfe;
  border-radius: 0.5rem;
  padding: 0.75rem;
}

.insight-box h3 {
  font-size: 0.85rem;
  color: #1e40af;
  margin-bottom: 0.5rem;
}

.insight-box p {
  font-size: 0.8rem;
  color: #1e3a8a;
  line-height: 1.4;
  margin-bottom: 0.5rem;
}

.insight-box p:last-child {
  margin-bottom: 0;
}

.disclaimer {
  background: #f9fafb;
  border-radius: 0.5rem;
  padding: 0.75rem;
  font-size: 0.75rem;
  color: #6b7280;
  line-height: 1.4;
}

.disclaimer strong {
  color: #4b5563;
}
